INSERT INTO item VALUES (398,'Protection, Ring +5','Ring',NULL,'No','Faint abjuration','5','50,000 gp',NULL,'Forge Ring, shield of faith, caster must be of a level at least three times greater than the bonus of the ring',NULL,NULL,'\n      <div topic=\"Protection\" level=\"8\"><p><b>Protection:</b> This ring offers continual magical protection in the form of a deflection bonus of +1 to +5 to AC.</p><p>Faint abjuration; CL 5th; Forge Ring, <i>shield of faith</i>,  caster must be of a level at least three times greater than the bonus of the ring; Price 2,000 gp (<i>ring +1</i>), 8,000 gp (<i>ring +2</i>), 18,000 gp (<i>ring +3</i>), 32,000 gp (<i>ring +4</i>), 50,000 gp (<i>ring +5</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (399,'Ram','Ring',NULL,'No','Moderate transmutation','9','8,600 gp',NULL,'Forge Ring, bull\'s strength, telekinesis',NULL,NULL,'\n      <div topic=\"Ram\" level=\"8\"><p><b>Ram:</b> The <i>ring of the ram</i> is an ornate ring forged of hard metal, usually iron or an iron alloy. It has the head of a ram as its device.</p><p>The wearer can command the ring to give forth a ramlike force, manifested by a vaguely discernible shape that resembles the head of a ram or a goat. This force strikes a single target, dealing 1d6 points of damage if 1 charge is expended, 2d6 points if 2 charges are used, or 3d6 points if 3 charges (the maximum) are used. Treat this as a ranged attack with a 50-foot maximum range and no penalties for distance.</p><p>The force of the blow is considerable, and those struck by the ring are subject to a bull rush if within 30 feet of the ring-wearer. (The ram has Strength 25 and is Large.) The ram gains a +1 bonus on the bull rush attempt if 2 charges are expended, or +2 if 3 charges are expended.</p><p>In addition to its attack mode, the <i>ring of the ram</i> also has the power to open doors as if it were a character with Strength 25. If 2 charges are expended, the effect is equivalent to a character with Strength 27. If 3 charges are expended, the effect is that of a character with Strength 29.</p><p>A newly created ring has 50 charges. When all the charges are expended, the ring becomes a nonmagical item.</p><p>Moderate transmutation; CL 9th; Forge Ring, <i>bull\'s strength</i>,  <i>telekinesis</i>; Price 8,600 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (400,'Regeneration','Ring',NULL,'No','Strong conjuration','15','90,000 gp',NULL,'Forge Ring, regenerate',NULL,NULL,'\n      <div topic=\"Regeneration\" level=\"8\"><p><b>Regeneration:</b> This white gold ring continually allows a living wearer to heal 1 point of damage per level every hour rather than every day. (This ability cannot be aided by the Heal skill.) Nonlethal damage heals at a rate of 1 point of damage per level every 5 minutes. If the wearer loses a limb, an organ, or any other body part while wearing this ring, the ring <i>regenerates</i> it as the spell. In either case, only damage taken while wearing the ring is regenerated.</p><p>Strong conjuration; CL 15th; Forge Ring, <i>regenerate</i>; Price 90,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (401,'Shooting Stars','Ring',NULL,'No','Strong evocation','12','50,000 gp',NULL,'Forge Ring, light, faerie fire, fireball, lightning bolt',NULL,NULL,'\n      <div topic=\"Shooting Stars\" level=\"8\"><p><b>Shooting Stars:</b> This ring has two modes of operation, one for being in shadowy darkness or outdoors at night and a second one when the wearer is underground or indoors at night.</p><p>During the night under the open sky or in areas of shadow or darkness, the <i>ring of shooting stars</i> can perform the following functions on command.</p><ul>\n <li> <i>Dancing lights</i> (once per hour)</li>\n <li> <i>Light</i> (twice per night)</li>\n <li> <i>Ball lightning</i> (special, once per night)</li>\n <li> <i>Shooting stars</i> (special, three per week)</li>\n</ul><p>The first special function, <i>ball lightning</i>,  releases one to four balls of lightning (ring wearer\'s choice). These glowing globes resemble <i>dancing lights</i>, and the ring wearer controls them in the same fashion (see the <i>Dancing lights</i> spell description). The spheres have a 120-foot range and a duration of 4 rounds. They can be moved at 120 feet per round. Each sphere is about 3 feet in diameter, and any creature who comes within 5 feet of one causes its charge to dissipate, taking electricity damage in the process according to the number of balls created.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Number of Balls</b><br/></td>\n<td><b>Damage per Ball</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>4 lightning balls<br/></td>\n<td>1d6 points of damage each<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>3 lightning balls<br/></td>\n<td>2d6 points of damage each<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2 lightning balls<br/></td>\n<td>3d6 points of damage each<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1 lightning ball<br/></td>\n<td>4d6 points of damage<br/></td>\n\n</tr>\n</table><p>Once the <i>Ball lightning</i> function is activated, the balls can be released at any time before the sun rises. (Multiple balls can be released in the same round.)</p><p>The second special function produces three <i>Shooting stars</i> that can be released from the ring each week, simultaneously or one at a time. They impact for 12 points of damage and spread (as a <i>fireball</i>) in a 5-foot-radius sphere for 24 points of fire damage.</p><p>Any creature struck by a <i>shooting star</i> takes full damage from impact plus full fire damage from the spread unless it makes a DC 13 Reflex save. Creatures not struck but within the spread ignore the impact damage and take only half damage from the fire spread on a successful DC 13 Reflex save. Range is 70 feet, at the end of which the <i>shooting star</i> explodes, unless it strikes a creature or object before that. A <i>shooting star</i> always follows a straight line, and any creature in its path must make a save or be hit by the projectile.</p><p>Indoors at night, or underground, the <i>ring of shooting stars</i> has the following properties.</p><ul>\n <li> <i>Faerie fire</i> (twice per day)</li>\n <li> <i>Spark shower</i> (special, once per day)</li>\n</ul><p>The <i>Spark shower</i> is a flying cloud of sizzling purple sparks that fan out from the ring for a distance of 20 feet in an arc 10 feet wide. Creatures within this area take 2d8 points of damage each if not wearing metal armor or carrying a metal weapon. Those wearing metal armor and/or carrying a metal weapon take 4d8 points of damage.</p><p>Strong evocation; CL 12th; Forge Ring, <i>light</i>,  <i>faerie fire</i>,  <i>fireball</i>,  <i>lightning bolt</i>; Price 50,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (402,'Spell Storing, Minor','Ring',NULL,'No','Faint evocation','5','18,000 gp',NULL,'Forge Ring, imbue with spell ability',NULL,NULL,'\n      <div topic=\"Spell Storing, Minor\" level=\"8\"><p><b>Spell Storing, Minor:</b> A <i>minor ring of spell storing</i> contains up to three levels of spells that the wearer can cast. Each spell has a caster level equal to the minimum level needed to cast that spell. The user need not provide any material components or focus, or pay an XP cost to cast the spell, and there is no arcane spell failure chance for wearing armor (because the ring wearer need not gesture). The activation time for the ring is same as the casting time for the relevant spell, with a minimum of 1 standard action.</p><p>For a randomly generated ring, treat it as a scroll to determine what spells are stored in it. If you roll a spell that would put the ring over the three-level limit, ignore that roll; the ring has no more spells in it. (Not every newly discovered ring need be fully charged.)</p><p>A spellcaster can cast any spells into the ring, so long as the total spell levels do not add up to more than three. Metamagic versions of spells take up storage space equal to their spell level modified by the metamagic feat. A spellcaster can use a scroll to put a spell into the <i>minor ring of spell storing</i>.</p><p>The ring magically imparts to the wearer the names of all spells currently stored within it.</p><p>Faint evocation; CL 5th; Forge Ring, <i>imbue with spell ability</i>; Price 18,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (403,'Spell Storing','Ring',NULL,'No','Moderate evocation','9','50,000 gp',NULL,'Forge Ring, imbue with spell ability',NULL,NULL,'\n      <div topic=\"Spell Storing\" level=\"8\"><p><b>Spell Storing:</b> As the <i>minor ring of spell storing</i>,  except it holds up to five levels of spells.</p><p>Moderate evocation; CL 9th; Forge Ring, <i>imbue with spell ability</i>; Price 50,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (404,'Spell Storing, Major','Ring',NULL,'No','Strong evocation','17','200,000 gp',NULL,'Forge Ring, imbue with spell ability',NULL,NULL,'\n      <div topic=\"Spell Storing, Major\" level=\"8\"><p><b>Spell Storing, Major:</b> As the <i>minor ring of spell storing</i>,  except it holds up to ten levels of spells.</p><p>Strong evocation; CL 17th; Forge Ring, <i>imbue with spell ability</i>; Price 200,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (405,'Spell Turning','Ring',NULL,'No','Strong abjuration','13','98,280 gp',NULL,'Forge Ring, spell turning',NULL,NULL,'\n      <div topic=\"Spell Turning\" level=\"8\"><p><b>Spell Turning:</b> Up to three times per day on command, this simple platinum band automatically reflects the next nine levels of spells cast at the wearer, exactly as if <i>spell turning</i> had been cast upon the wearer.</p><p>Strong abjuration; CL 13th; Forge Ring, <i>spell turning</i>; Price 98,280 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (406,'Sustenance','Ring',NULL,'No','Faint conjuration','5','2,500 gp',NULL,'Forge Ring, create food and water',NULL,NULL,'\n      <div topic=\"Sustenance\" level=\"8\"><p><b>Sustenance:</b> This ring continually provides its wearer with life-sustaining nourishment. The ring also refreshes the body and mind, so that its wearer needs only sleep 2 hours per day to gain the benefit of 8 hours of sleep. The ring must be worn for a full week before it begins to work. If it is removed, the owner must wear it for another week to reattune it to himself.</p><p>Faint conjuration; CL 5th; Forge Ring, <i>create food and water</i>; Price 2,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (407,'Swimming','Ring',NULL,'No','Faint transmutation','2','2,500 gp',NULL,'Forge Ring, creator must have 5 ranks in the Swim skill',NULL,NULL,'\n      <div topic=\"Swimming\" level=\"8\"><p><b>Swimming:</b> This silver ring has a wave pattern etched into the band. It continually grants the wearer a +5 competence bonus on Swim checks.</p><p>Faint transmutation; CL 2nd; Forge Ring, creator must have 5 ranks in the Swim skill; Price 2,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (408,'Swimming, Improved','Ring',NULL,'No','Moderate transmutation','7','10,000 gp',NULL,'Forge Ring, creator must have 10 ranks in the Swim skill',NULL,NULL,'\n      <div topic=\"Swimming, Improved\" level=\"8\"><p><b>Swimming, Improved:</b> As swimming, except it grants a +10 competence bonus on its wearer\'s Swim checks.</p><p>Moderate transmutation; CL 7th; Forge Ring, creator must have 10 ranks in the Swim skill; Price 10,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (409,'Telekinesis','Ring',NULL,'No','Moderate transmutation','9','75,000 gp',NULL,'Forge Ring, telekinesis',NULL,NULL,'\n      <div topic=\"Telekinesis\" level=\"8\"><p><b>Telekinesis:</b> This ring allows the caster to use the spell <i>telekinesis</i> on command.</p><p>Moderate transmutation; CL 9th; Forge Ring, <i>telekinesis</i>; Price 75,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (410,'Three Wishes','Ring',NULL,'No','Strong evocation (if miracle is used)','20','97,950 gp',NULL,'Forge Ring, wish or miracle','11,475 gp + 15,918 XP',NULL,'\n      <div topic=\"Three Wishes\" level=\"8\"><p><b>Three Wishes:</b> This ring is set with three rubies. Each ruby stores a <i>wish</i> spell, activated by the ring. When a <i>wish</i> is used, that ruby disappears. For a randomly generated ring, roll 1d3 to determine the remaining number of rubies. When all the <i>wishes</i> are used, the ring becomes a nonmagical item.</p><p>Strong evocation (if <i>miracle</i> is used); CL 20th; Forge Ring, <i>wish</i> or <i>miracle</i>; Price 97,950 gp; Cost 11,475 gp + 15,918 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (411,'Water Walking','Ring',NULL,'No','Moderate transmutation','9','15,000 gp',NULL,'Forge Ring, water walk',NULL,NULL,'\n      <div topic=\"Water Walking\" level=\"8\"><p><b>Water Walking:</b> This ring, set with an opal, allows the wearer to continually utilize the effects of the spell <i>water walk</i>.</p><p>Moderate transmutation; CL 9th; Forge Ring, <i>water walk</i>; Price 15,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (412,'Wizardry I','Ring',NULL,'No','Moderate (wizardry I) or strong (wizardry II-IV) (no school)','11','20,000 gp',NULL,'Forge Ring, limited wish',NULL,NULL,'\n      <div topic=\"Wizardry\" level=\"8\"><p><b>Wizardry:</b> This special ring comes in four kinds (<i>ring of wizardry I</i>,  <i>ring of wizardry II</i>,  <i>ring of wizardry III</i>,  and <i>ring of wizardry IV</i>), all of them useful only to arcane spellcasters. The wearer\'s arcane spells per day are doubled for one specific spell level. A <i>ring of wizardry I</i> doubles 1st-level spells, a <i>ring of wizardry II</i> doubles 2nd-level spells, a <i>ring of wizardry III</i> doubles 3rd-level spells, and a <i>ring of wizardry IV</i> doubles 4th-level spells. Bonus spells from high ability scores or school specialization are not doubled.</p><p>Moderate (<i>wizardry I</i>) or strong (<i>wizardry II-IV</i>) (no school); CL 11th (<i>I</i>), 14th (<i>II</i>), 17th (<i>III</i>), 20th (<i>IV</i>); Forge Ring, <i>limited wish</i>; Price 20,000 gp (<i>I</i>), 40,000 gp (<i>II</i>), 70,000 gp (<i>III</i>), 100,000 gp (<i>IV</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (413,'Wizardry II','Ring',NULL,'No','Moderate (wizardry I) or strong (wizardry II-IV) (no school)','11','40,000 gp',NULL,'Forge Ring, limited wish',NULL,NULL,'\n      <div topic=\"Wizardry\" level=\"8\"><p><b>Wizardry:</b> This special ring comes in four kinds (<i>ring of wizardry I</i>,  <i>ring of wizardry II</i>,  <i>ring of wizardry III</i>,  and <i>ring of wizardry IV</i>), all of them useful only to arcane spellcasters. The wearer\'s arcane spells per day are doubled for one specific spell level. A <i>ring of wizardry I</i> doubles 1st-level spells, a <i>ring of wizardry II</i> doubles 2nd-level spells, a <i>ring of wizardry III</i> doubles 3rd-level spells, and a <i>ring of wizardry IV</i> doubles 4th-level spells. Bonus spells from high ability scores or school specialization are not doubled.</p><p>Moderate (<i>wizardry I</i>) or strong (<i>wizardry II-IV</i>) (no school); CL 11th (<i>I</i>), 14th (<i>II</i>), 17th (<i>III</i>), 20th (<i>IV</i>); Forge Ring, <i>limited wish</i>; Price 20,000 gp (<i>I</i>), 40,000 gp (<i>II</i>), 70,000 gp (<i>III</i>), 100,000 gp (<i>IV</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (414,'Wizardry III','Ring',NULL,'No','Moderate (wizardry I) or strong (wizardry II-IV) (no school)','11','70,000 gp',NULL,'Forge Ring, limited wish',NULL,NULL,'\n      <div topic=\"Wizardry\" level=\"8\"><p><b>Wizardry:</b> This special ring comes in four kinds (<i>ring of wizardry I</i>,  <i>ring of wizardry II</i>,  <i>ring of wizardry III</i>,  and <i>ring of wizardry IV</i>), all of them useful only to arcane spellcasters. The wearer\'s arcane spells per day are doubled for one specific spell level. A <i>ring of wizardry I</i> doubles 1st-level spells, a <i>ring of wizardry II</i> doubles 2nd-level spells, a <i>ring of wizardry III</i> doubles 3rd-level spells, and a <i>ring of wizardry IV</i> doubles 4th-level spells. Bonus spells from high ability scores or school specialization are not doubled.</p><p>Moderate (<i>wizardry I</i>) or strong (<i>wizardry II-IV</i>) (no school); CL 11th (<i>I</i>), 14th (<i>II</i>), 17th (<i>III</i>), 20th (<i>IV</i>); Forge Ring, <i>limited wish</i>; Price 20,000 gp (<i>I</i>), 40,000 gp (<i>II</i>), 70,000 gp (<i>III</i>), 100,000 gp (<i>IV</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (415,'Wizardry IV','Ring',NULL,'No','Moderate (wizardry I) or strong (wizardry II-IV) (no school)','11','100,000 gp',NULL,'Forge Ring, limited wish',NULL,NULL,'\n      <div topic=\"Wizardry\" level=\"8\"><p><b>Wizardry:</b> This special ring comes in four kinds (<i>ring of wizardry I</i>,  <i>ring of wizardry II</i>,  <i>ring of wizardry III</i>,  and <i>ring of wizardry IV</i>), all of them useful only to arcane spellcasters. The wearer\'s arcane spells per day are doubled for one specific spell level. A <i>ring of wizardry I</i> doubles 1st-level spells, a <i>ring of wizardry II</i> doubles 2nd-level spells, a <i>ring of wizardry III</i> doubles 3rd-level spells, and a <i>ring of wizardry IV</i> doubles 4th-level spells. Bonus spells from high ability scores or school specialization are not doubled.</p><p>Moderate (<i>wizardry I</i>) or strong (<i>wizardry II-IV</i>) (no school); CL 11th (<i>I</i>), 14th (<i>II</i>), 17th (<i>III</i>), 20th (<i>IV</i>); Forge Ring, <i>limited wish</i>; Price 20,000 gp (<i>I</i>), 40,000 gp (<i>II</i>), 70,000 gp (<i>III</i>), 100,000 gp (<i>IV</i>).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (416,'X-Ray Vision','Ring',NULL,'No','Moderate divination','6','25,000 gp',NULL,'Forge Ring, true seeing',NULL,NULL,'\n      <div topic=\"X-Ray Vision\" level=\"8\"><p><b>X-Ray Vision:</b> On command, this ring gives its possessor the ability to see into and through solid matter. Vision range is 20 feet, with the viewer seeing as if he were looking at something in normal light even if there is no illumination. X-ray vision can penetrate 1 foot of stone, 1 inch of common metal, or up to 3 feet of wood or dirt. Thicker substances or a thin sheet of lead blocks the vision.</p><p>Using the ring is physically exhausting, causing the wearer 1 point of Constitution damage per minute after the first 10 minutes of use in a single day.</p><p>Moderate divination; CL 6th; Forge Ring, <i>true seeing</i>; Price 25,000 gp.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (417,'Absorption','Rod',NULL,'No','Strong abjuration','15','50,000 gp',NULL,'Craft Rod, spell turning',NULL,NULL,'\n      <div topic=\"Absorption\" level=\"8\"><p><b>Absorption:</b> This rod acts as a magnet, drawing spells or spell-like abilities into itself. The magic absorbed must be a single-target spell or a ray directed at either the character possessing the rod or her gear. The rod then nullifies the spell\'s effect and stores its potential until the wielder releases this energy in the form of spells of her own. She can instantly detect a spell\'s level as the rod absorbs that spell\'s energy. Absorption requires no action on the part of the user if the rod is in hand at the time.</p><p>A running total of absorbed (and used) spell levels should be kept. The wielder of the rod can use captured spell energy to cast any spell she has prepared, without expending the preparation itself. The only restrictions are that the levels of spell energy stored in the rod must be equal to or greater than the level of the spell the wielder wants to cast, that any material components required for the spell be present, and that the rod be in hand when casting. For casters such as bards or sorcerers who do not prepare spells, the rod\'s energy can be used to cast any spell of the appropriate level or levels that they know.</p><p>A <i>rod of absorption</i> absorbs a maximum of fifty spell levels and can thereafter only discharge any remaining potential it might have. The rod cannot be recharged. The wielder knows the rod\'s remaining absorbing potential and current amount of stored energy.</p><p>To determine the absorption potential remaining in a newly found rod, roll d% and divide the result by 2. Then roll d% again: On a result of 71-100, half the levels already absorbed by the rod are still stored within.</p><p>Strong abjuration; CL 15th; Craft Rod, <i>spell turning</i>; Price 50,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (418,'Alertness','Rod',NULL,'No','Moderate abjuration, divination, enchantment, and evocation','11','85,000 gp',NULL,'Craft Rod, alarm, detect chaos, detect evil, detect good, detect law, detect magic, discern lies, light, see invisibility, prayer, animate objects',NULL,NULL,'\n      <div topic=\"Alertness\" level=\"8\"><p><b>Alertness:</b> This rod is indistinguishable from a <i>+1 light mace</i>. It has eight flanges on its macelike head. The rod bestows a +1 insight bonus on initiative checks. If grasped firmly, the rod enables the holder to use <i>detect evil</i>,  <i>detect good</i>,  <i>detect chaos</i>,  <i>detect law</i>, <i>detect magic</i>,  <i>discern lies</i>,  <i>light</i>,  or <i>see invisibility</i>. Each different use is a standard action.</p><p>If the head of a <i>rod of alertness</i> is planted in the ground, and the possessor wills it to alertness (a standard action), the rod senses any creature within 120 feet who intends to harm the possessor. At the same time, the rod creates the effect of a <i>prayer</i> spell upon all creatures friendly to the possessor in a 20-foot radius. Immediately thereafter, the rod sends forth a mental alert to these friendly creatures, warning them of possible danger from the unfriendly creature or creatures within the 120-foot radius. These effects last for 10 minutes, and the rod can perform this function once per day. Last, the rod can be used to simulate the casting of an <i>animate objects</i> spell, utilizing any eleven (or fewer) Small objects located roughly around the perimeter of a 5-foot-radius circle centered on the rod when planted in the ground. Objects remain animated for 11 rounds. The rod can perform this function once per day.</p><p>Moderate abjuration, divination, enchantment, and evocation; CL 11th; Craft Rod, <i>alarm</i>,  <i>detect chaos</i>,  <i>detect evil</i>,  <i>detect good</i>,  <i>detect law</i>,  <i>detect magic</i>,  <i>discern lies</i>,  <i>light</i>,  <i>see invisibility</i>,  <i>prayer</i>,  <i>animate objects</i>; Price 85,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (419,'Cancellation','Rod',NULL,'No','Strong abjuration','17','11,000 gp',NULL,'Craft Rod, mage\'s disjunction',NULL,NULL,'\n      <div topic=\"Cancellation\" level=\"8\"><p><b>Cancellation:</b> This dreaded rod is a bane to magic items, for its touch drains an item of all magical properties. The item touched must make a DC 23 Will save to prevent the rod from draining it. If a creature is holding it at the time, then the item can use the holder\'s Will save bonus in place of its own if the holder\'s is better. In such cases, contact is made by making a melee touch attack roll. Upon draining an item, the rod itself becomes brittle and cannot be used again. Drained items are only restorable by <i>wish</i> or <i>miracle</i>. (If a <i>sphere of annihilation</i> and a <i>rod of cancellation</i> negate each other, nothing can restore either of them.)</p><p>Strong abjuration; CL 17th; Craft Rod, <i>mage\'s disjunction</i>; Price 11,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (420,'Enemy Detection','Rod',NULL,'No','Moderate divination','10','23,500 gp',NULL,'Craft Rod, true seeing',NULL,NULL,'\n      <div topic=\"Enemy Detection\" level=\"8\"><p><b>Enemy Detection:</b> This device pulses in the wielder\'s hand and points in the direction of any creature or creatures hostile to the bearer of the device (nearest ones first). These creatures can be invisible, ethereal, hidden, disguised, or in plain sight. Detection range is 60 feet. If the bearer of the rod concentrates for a full round, the rod pinpoints the location of the nearest enemy and indicates how many enemies are within range. The rod can be used three times each day, each use lasting up to 10 minutes. Activating the rod is a standard action.</p><p>Moderate divination; CL 10th; Craft Rod, <i>true seeing</i>; Price 23,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (421,'Flailing','Rod',NULL,'No','Moderate enchantment','9','50,000 gp',NULL,'Craft Rod, Craft Magic Arms and Armor, bless',NULL,NULL,'\n      <div topic=\"Flailing\" level=\"8\"><p><b>Flailing:</b> Upon the command of its possessor, the rod activates, changing from a normal-seeming rod to a <i>+3 dire flail</i>. The dire flail is a double weapon, which means that each of the weapon\'s heads can be used to attack. The wielder can gain an extra attack (with the second head) at the cost of making all attacks at a -2 penalty (as if she had the Two-Weapon Fighting feat).</p><p>Once per day the wielder can use a free action to cause the rod to grant her a +4 deflection bonus to Armor Class and a +4 resistance bonus on saving throws for 10 minutes. The rod need not be in weapon form to grant this benefit.</p><p>Transforming it into a weapon or back into a rod is a move action.</p><p>Moderate enchantment; CL 9th; Craft Rod, Craft Magic Arms and Armor, <i>bless</i>; Price 50,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (422,'Flame Extinguishing','Rod',NULL,'No','Strong transmutation','12','15,000 gp',NULL,'Craft Rod, pyrotechnics',NULL,NULL,'\n      <div topic=\"Flame Extinguishing\" level=\"8\"><p><b>Flame Extinguishing:</b> This rod can extinguish Medium or smaller nonmagical fires with simply a touch (a standard action). For the rod to be effective against other sorts of fires, the wielder must expend 1 or more of the rod\'s charges.</p><p>Extinguishing a Large or larger nonmagical fire, or a magic fire of Medium or smaller (such as that of a flaming weapon or a <i>burning hands</i> spell), expends 1 charge. Continual magic flames, such as those of a weapon or a fire creature, are suppressed for 6 rounds and flare up again after that time. To extinguish an instantaneous fire spell, the rod must be within the area of the effect and the wielder must have used a ready action, effectively countering the entire spell.</p><p>When applied to Large or larger magic fires, such as those caused by <i>fireball</i>,  <i>flame strike</i>,  or <i>wall of fire</i>, extinguishing the flames expends 2 charges from the rod.</p><p>If the device is used upon a fire creature (a melee touch attack), it deals 6d6 points of damage to the creature. This use requires 3 charges.</p><p>A <i>rod of flame extinguishing</i> has 10 charges when found. Spent charges are renewed every day, so that a wielder can expend up to 10 charges in any 24-hour period.</p><p>Strong transmutation; CL 12th; Craft Rod, <i>pyrotechnics</i>; Price 15,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (423,'Immovable Rod','Rod',NULL,'No','Moderate transmutation','10','5,000 gp',NULL,'Craft Rod, levitate',NULL,NULL,'\n      <div topic=\"Immovable Rod\" level=\"8\"><p><b>Immovable Rod:</b> This rod is a flat iron bar with a small button on one end. When the button is pushed (a move action), the rod does not move from where it is, even if staying in place defies gravity. Thus, the owner can lift or place the rod wherever he wishes, push the button, and let go. Several <i>immovable rods</i> can even make a ladder when used together (although only two are needed). An <i>immovable rod</i> can support up to 8,000 pounds before falling to the ground. If a creature pushes against an <i>immovable rod</i>,  it must make a DC 30 Strength check to move the rod up to 10 feet in a single round.</p><p>Moderate transmutation; CL 10th; Craft Rod, <i>levitate</i>; Price 5,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (424,'Lordly Might','Rod',NULL,'No','Strong enchantment, evocation, necromancy, and transmutation','19','70,000 gp',NULL,'Craft Rod, Craft Magic Arms and Armor, inflict light wounds, bull\'s strength, flame blade, hold person, fear',NULL,NULL,'\n      <div topic=\"Lordly Might\" level=\"8\"><p><b>Lordly Might:</b> This rod has functions that are spell-like, and it can also be used as a magic weapon of various sorts. It also has several more mundane uses. The <i>rod of lordly might</i> is metal, thicker than other rods, with a flanged ball at one end and six studlike buttons along its length. (Pushing any of the rod\'s buttons is equivalent to drawing a weapon.) It weighs 10 pounds.</p><p>The following spell-like functions of the rod can each be used once per day.</p><ul>\n <li> <i>Hold person</i> upon touch, if the wielder so commands (Will DC 14 negates). The wielder must choose to use this power and then succeed on a melee touch attack to activate the power. If the attack fails, the effect is lost.</li>\n <li> <i>Fear</i> upon all enemies viewing it, if the wielder so desires (10-foot maximum range, Will DC 16 partial). Invoking this power is a standard action.</li>\n <li> Deal 2d4 hit points of damage to an opponent on a successful touch attack (Will DC 17 half ) and cure the wielder of a like amount of damage. The wielder must choose to use this power before attacking, as with <i>hold person</i>.</li>\n</ul><p>The following weapon functions of the rod have no limit on the number of times they can be employed.</p><ul>\n <li> In its normal form, the rod can be used as a <i>+2 light mace</i>.</li>\n <li> When button 1 is pushed, the rod becomes a <i>+1 flaming longsword</i>. A blade springs from the ball, with the ball itself becoming the sword\'s hilt. The weapon lengthens to an overall length of 4 feet.</li>\n <li> When button 2 is pushed, the rod becomes a <i>+4 battleaxe</i>. A wide blade springs forth at the ball, and the whole lengthens to 4 feet.</li>\n <li> When button 3 is pushed, the rod becomes a <i>+3 shortspear</i> or <i>+3 longspear</i>. The spear blade springs forth, and the handle can be lengthened up to 12 feet (wielder\'s choice), for an overall length of from 6 feet to 15 feet. At its 15-foot length, the rod is suitable for use as a lance.</li>\n</ul><p>The following other functions of the rod also have no limit on the number of times they can be employed.</p><ul>\n <li> Climbing pole/ladder. When button 4 is pushed, a spike that can anchor in granite is extruded from the ball, while the other end sprouts three sharp hooks. The rod lengthens to anywhere between 5 and 50 feet in a single round, stopping when button 4 is pushed again. Horizontal bars three inches long fold out from the sides, 1 foot apart, in staggered progression. The rod is firmly held by the spike and hooks and can bear up to 4,000 pounds. The wielder can retract the pole by pushing button 5.</li>\n <li> The ladder function can be used to force open doors. The wielder plants the rod\'s base 30 feet or less from the portal to be forced and in line with it, then pushes button 4. The force exerted has a Strength modifier of +12.</li>\n <li> When button 6 is pushed, the rod indicates magnetic north and gives the wielder a knowledge of his approximate depth beneath the surface or height above it.</li>\n</ul><p>Strong enchantment, evocation, necromancy, and transmutation; CL 19th; Craft Rod, Craft Magic Arms and Armor, <i>inflict light wounds</i>,  <i>bull\'s strength</i>,  <i>flame blade</i>,  <i>hold person</i>,  <i>fear</i>; Price 70,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (425,'Metal and Mineral Detection','Rod',NULL,'No','Moderate divination','9','10,500 gp',NULL,'Craft Rod, locate object',NULL,NULL,'\n      <div topic=\"Metal and Mineral Detection\" level=\"8\"><p><b>Metal and Mineral Detection:</b> This rod pulses in the wielder\'s hand and points to the largest mass of metal within 30 feet. However, the wielder can concentrate on a specific metal or mineral. If the specific mineral is within 30 feet, the rod points to any places it is located, and the rod wielder knows the approximate quantity as well. If more than one deposit of the specified metal or mineral is within range, the rod points to the largest cache first. Each operation requires a full-round action.</p><p>Moderate divination; CL 9th; Craft Rod, <i>locate object</i>; Price 10,500 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (426,'Metamagic, Empower, Lesser','Rod',NULL,'No','Strong (no school)','17','9,000 gp',NULL,'Craft Rod, Empower Spell',NULL,NULL,'\n      <div topic=\"Metamagic, Empower\" level=\"8\"><p><b>Metamagic, Empower:</b> The wielder can cast up to three spells per day that are empowered as though using the Empower Spell feat.</p><p>Strong (no school); CL 17th; Craft Rod, Empower Spell; Price 9,000 gp (lesser), 32,500 gp (normal), 73,000 gp (greater).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (427,'Metamagic, Empower, Normal','Rod',NULL,'No','Strong (no school)','17','32,500 gp',NULL,'Craft Rod, Empower Spell',NULL,NULL,'\n      <div topic=\"Metamagic, Empower\" level=\"8\"><p><b>Metamagic, Empower:</b> The wielder can cast up to three spells per day that are empowered as though using the Empower Spell feat.</p><p>Strong (no school); CL 17th; Craft Rod, Empower Spell; Price 9,000 gp (lesser), 32,500 gp (normal), 73,000 gp (greater).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
