INSERT INTO item VALUES (441,'Metamagic, Silent, Lesser','Rod',NULL,'No','Strong (no school)','17','3,000 gp',NULL,'Craft Rod, Silent Spell',NULL,NULL,'\n      <div topic=\"Metamagic, Silent\" level=\"8\"><p><b>Metamagic, Silent:</b> The wielder can cast up to three spells per day without verbal components as though using the Silent Spell feat.</p><p>Strong (no school); CL 17th; Craft Rod, Silent Spell; Price 3,000 gp (lesser), 11,000 gp (normal), 24,500 gp (greater).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (442,'Metamagic, Silent, Normal','Rod',NULL,'No','Strong (no school)','17','11,000 gp',NULL,'Craft Rod, Silent Spell',NULL,NULL,'\n      <div topic=\"Metamagic, Silent\" level=\"8\"><p><b>Metamagic, Silent:</b> The wielder can cast up to three spells per day without verbal components as though using the Silent Spell feat.</p><p>Strong (no school); CL 17th; Craft Rod, Silent Spell; Price 3,000 gp (lesser), 11,000 gp (normal), 24,500 gp (greater).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (443,'Metamagic, Silent, Greater','Rod',NULL,'No','Strong (no school)','17','24,500 gp',NULL,'Craft Rod, Silent Spell',NULL,NULL,'\n      <div topic=\"Metamagic, Silent\" level=\"8\"><p><b>Metamagic, Silent:</b> The wielder can cast up to three spells per day without verbal components as though using the Silent Spell feat.</p><p>Strong (no school); CL 17th; Craft Rod, Silent Spell; Price 3,000 gp (lesser), 11,000 gp (normal), 24,500 gp (greater).</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (444,'Negation','Rod',NULL,'No','Strong varied','15','37,000 gp',NULL,'Craft Rod, dispel magic, and limited wish or miracle',NULL,NULL,'\n      <div topic=\"Negation\" level=\"8\"><p><b>Negation:</b> This device negates the spell or spell-like function or functions of magic items. The wielder points the rod at the magic item, and a pale gray beam shoots forth to touch the target device, attacking as a ray (a ranged touch attack). The ray functions as a <i>greater dispel magic</i> spell, except it only affects magic items. To negate instantaneous effects from an item, the rod wielder needs to have used a ready action. The dispel check uses the rod\'s caster level (15th). The target item gets no saving throw, although the rod can\'t negate artifacts (even minor artifacts). The rod can function three times per day.</p><p>Strong varied; CL 15th; Craft Rod, <i>dispel magic</i>,  and <i>limited wish</i> or <i>miracle</i>; Price 37,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (445,'Python','Rod',NULL,'No','Moderate transmutation','10','13,000 gp',NULL,'Craft Rod, Craft Magic Arms and Armor, baleful polymorph, creator must be good',NULL,NULL,'\n      <div topic=\"Python\" level=\"8\"><p><b>Python:</b> This rod is longer than normal rods. It is about 4 feet long and weighs 10 pounds. It strikes as a <i>+1/+1 quarterstaff</i>. If the user throws the rod to the ground (a standard action), it grows to become a giant constrictor snake by the end of the round. The python obeys all commands of the owner. (In animal form, it retains the +1 enhancement bonus on attacks and damage possessed by the rod form.) The serpent returns to rod form (a full-round action) whenever the wielder desires, or whenever it moves farther than 100 feet from the owner. If the snake form is slain, it returns to rod form and cannot be activated again for three days. A <i>python rod</i> only functions if the possessor is good.</p><p>Moderate transmutation; CL 10th; Craft Rod, Craft Magic Arms and Armor, <i>baleful polymorph</i>,  creator must be good; Price 13,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (446,'Rulership','Rod',NULL,'No','Strong enchantment','20','60,000 gp',NULL,'Craft Rod, mass charm monster','27,500 gp + 2,200 XP',NULL,'\n      <div topic=\"Rulership\" level=\"8\"><p><b>Rulership:</b> This rod looks like a royal scepter worth at least 5,000 gp in materials and workmanship alone. The wielder can command the obedience and fealty of creatures within 120 feet when she activates the device (a standard action). Creatures totaling 300 Hit Dice can be ruled, but creatures with Intelligence scores of 12 or higher are entitled to a DC 16 Will save to negate the effect. Ruled creatures obey the wielder as if she were their absolute sovereign. Still, if the wielder gives a command that is contrary to the nature of the creatures commanded, the magic is broken. The rod can be used for 500 total minutes before crumbling to dust. This duration need not be continuous.</p><p>Strong enchantment; CL 20th; Craft Rod, <i>mass charm monster</i>; Price 60,000 gp; Cost 27,500 gp + 2,200 XP.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (447,'Security','Rod',NULL,'No','Strong conjuuration','20','61,000 gp',NULL,'Craft Rod, gate',NULL,NULL,'\n      <div topic=\"Security\" level=\"8\"><p><b>Security:</b> This item creates a nondimensional space, a pocket paradise. There the rod\'s possessor and as many as 199 other creatures can stay in complete safety for a period of time, up to 200 days divided by the number of creatures affected. All fractions are rounded down.</p><p>In this pocket paradise, creatures don\'t age, and natural healing take place at twice the normal rate. Fresh water and food (fruits and vegetables only) are in abundance. The climate is comfortable for all creatures involved.</p><p>Activating the rod (a standard action) causes the wielder and all creatures touching the rod to be transported instantaneously to the paradise. Members of large groups can hold hands or otherwise maintain physical contact, allowing all connected creatures in a circle or a chain to be affected by the rod. Unwilling creatures get a DC 17 Will save to negate the effect. If such a creature succeeds on its save, other creatures beyond that point in a chain can still be affected by the rod.</p><p>When the rod\'s effect expires or is dispelled, all the affected creatures instantly reappear in the location they occupied when the rod was activated. If something else occupies the space that a traveler would be returning to, then his body is displaced a sufficient distance to provide the space required for reentry. The rod\'s possessor can dismiss the effect whenever he wishes before the maximum time period expires, but the rod can only be activated once per week.</p><p>Strong conjuuration; CL 20th; Craft Rod, <i>gate</i>; Price 61,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (448,'Splendor','Rod',NULL,'No','Strong conjuration and transmutation','12','25,000 gp',NULL,'Craft Rod, eagle\'s splendor, fabricate, major creation',NULL,NULL,'\n      <div topic=\"Splendor\" level=\"8\"><p><b>Splendor:</b> The possessor of this rod gains a +4 enhancement bonus to her Charisma score for as long as she holds or carries the item. Once per day, the rod creates and garbs her in clothing of the finest fabrics, plus adornments of furs and jewels.</p><p>Apparel created by the magic of the rod remains in existence for 12 hours. However, if the possessor attempts to sell or give away any part of it, to use it for a spell component, or the like, all the apparel immediately disappears. The same applies if any of it is forcibly taken from her.</p><p>The value of noble garb created by the rod ranges from 7,000 to 10,000 gp (1d4+6 x1,000 gp)-1,000 gp for the fabric alone, 5,000 gp for the furs, and the rest for the jewel trim (maximum of twenty gems, maximum value 200 gp each).</p><p>In addition, the rod has a second special power, usable once per week. Upon command, it creates a palatial tent-a huge pavilion of silk 60 feet across. Inside the tent are temporary furnishings and food suitable to the splendor of the pavilion and sufficient to entertain as many as one hundred persons. The tent and its trappings last for one day. At the end of that time, the tent and all objects associated with it (including any items that were taken out of the tent) disappear.</p><p>Strong conjuration and transmutation; CL 12th; Craft Rod, <i>eagle\'s splendor</i>,  <i>fabricate</i>,  <i>major creation</i>; Price 25,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (449,'Thunder and Lightning','Rod',NULL,'No','Moderate evocation','9','33,000 gp',NULL,'Craft Rod, Craft Magic Arms and Armor, lightning bolt, shout',NULL,NULL,'\n      <div topic=\"Thunder and Lightning\" level=\"8\"><p><b>Thunder and Lightning:</b> Constructed of iron set with silver rivets, this rod has the properties of a <i>+2 light mace</i>. Its other magical powers are as follows.</p><ul>\n <li> <i>Thunder:</i> Once per day, the rod can strike as a <i>+3 light mace</i>,  and the opponent struck is stunned from the noise of the rod\'s impact (Fortitude DC 16 negates). Activating this power counts as a free action, and it works if the wielder strikes an opponent within 1 round.</li>\n <li> <i>Lightning:</i> Once per day, when the wielder desires, a short spark of electricity can leap forth when the rod strikes an opponent to deal the normal damage for a <i>+2 light mace</i> (1d6+2) and an extra 2d6 points of electricity damage. Even when the rod might not score a normal hit in combat, if the roll was good enough to count as a successful melee touch attack hit, then the 2d6 points of electricity damage still applies. The wielder activates this power as a free action, and it works if he strikes an opponent within 1 round.</li>\n <li> <i>Thunderclap:</i> Once per day as a standard action, the wielder can cause the rod to give out a deafening noise, just as a <i>shout</i> spell (Fortitude DC 16 partial, 2d6 points of sonic damage, target deafened for 2d6 rounds).</li>\n <li> <i>Lightning Stroke:</i> Once per day as a standard action, the wielder can cause the rod to shoot out a 5-foot-wide lightning bolt (9d6 points of electricity damage, Reflex DC 16 half ) to a range of 200 feet.</li>\n <li> <i>Thunder and Lightning:</i> Once per week as a standard action, the wielder of the rod can combine the <i>thunderclap</i> described above with a lightning bolt, as in the <i>lightning stroke</i>. The thunderclap affects all within 10 feet of the bolt. The <i>lightning stroke</i> deals 9d6 points of electricity damage (count rolls of 1 or 2 as rolls of 3, for a range of 27 to 54 points), and the <i>thunderclap</i> deals 2d6 points of sonic damage. A single DC 16 Reflex save applies for both effects.</li>\n</ul><p>Moderate evocation; CL 9th; Craft Rod, Craft Magic Arms and Armor, <i>lightning bolt</i>, <i>shout</i>; Price 33,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (450,'Viper','Rod',NULL,'No','Moderate necromancy','10','19,000 gp',NULL,'Craft Rod, Craft Magic Arms and Armor, poison, creator must be evil',NULL,NULL,'\n      <div topic=\"Viper\" level=\"8\"><p><b>Viper:</b> This rod strikes as a <i>+2 heavy mace</i>. Once per day, upon command, the head of the rod becomes that of an actual serpent for 10 minutes. During this period, any successful strike with the rod deals its usual damage and also poisons the creature hit. The poison deals 1d10 points of Constitution damage immediately (Fortitude DC 14 negates) and another 1d10 points of Constitution damage 1 minute later (Fortitude DC 14 negates). The rod only functions if its possessor is evil.</p><p>Moderate necromancy; CL 10th; Craft Rod, Craft Magic Arms and Armor, <i>poison</i>,  creator must be evil; Price 19,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (451,'Withering','Rod',NULL,'No','Strong necromancy','13','25,000 gp',NULL,'Craft Rod, Craft Magic Arms and Armor, contagion',NULL,NULL,'\n      <div topic=\"Withering\" level=\"8\"><p><b>Withering:</b> A <i>rod of withering</i> acts as a <i>+1 light mace</i> that deals no hit point damage. Instead, the wielder deals 1d4 points of Strength damage and 1d4 points of Constitution damage to any creature she touches with the rod (by making a melee touch attack). If she scores a critical hit, the damage from that hit is permanent ability drain. In either case, the defender negates the effect with a DC 17 Fortitude save.</p><p>Strong necromancy; CL 13th; Craft Rod, Craft Magic Arms and Armor, <i>contagion</i>; Price 25,000 gp.</p>\n</div>\n    ','SRD 3.5 MagicItemsIII');
INSERT INTO item VALUES (452,'Wonder','Rod',NULL,'No','Moderate enchantment','10','12,000 gp',NULL,'Craft Rod, confusion, creator must be chaotic',NULL,NULL,'\n      <div topic=\"Wonder\" level=\"8\"><p><b>Wonder:</b> A <i>rod of wonder</i> is a strange and unpredictable device that randomly generates any number of weird effects each time it is used. (Activating the rod is a standard action.) Typical powers of the rod include the following.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>d%</b><br/></td>\n<td><b>Wondrous Effect</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>01-05<br/></td>\n<td><i>Slow</i> creature pointed at for 10 rounds (Will DC 15 negates).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>06-10<br/></td>\n<td><i>Faerie fire</i> surrounds the target.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>11-15<br/></td>\n<td>Deludes wielder for 1 round into believing the rod functions as indicated by a second die roll (no save).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>16-20<br/></td>\n<td><i>Gust of wind</i>,  but at windstorm force (Fortitude DC 14 negates).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>21-25<br/></td>\n<td>Wielder learns target\'s surface thoughts (as with <i>detect thoughts)</i> for 1d4 rounds (no save).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>26-30<br/></td>\n<td><i>Stinking cloud</i> at 30-ft. range (Fortitude DC 15 negates).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>31-33<br/></td>\n<td>Heavy rain falls for 1 round in 60-ft. radius centered on rod wielder.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>34-36<br/></td>\n<td><i>Summon</i> an animal-a rhino (01-25 on d%), elephant (26-50), or mouse (51-100).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>37-46<br/></td>\n<td><i>Lightning bolt</i> (70 ft. long, 5 ft. wide), 6d6 damage (Reflex DC 15 half).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>47-49<br/></td>\n<td>Stream of 600 large butterflies pours forth and flutters around for 2 rounds, blinding everyone (including wielder) within 25 ft. (Reflex DC 14 negates).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>50-53<br/></td>\n<td><i>Enlarge person</i> if within 60 ft. of rod (Fortitude DC 13 negates).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>54-58<br/></td>\n<td><i>Darkness</i>, 30-ft. -diameter hemisphere, centered 30 ft. away from rod.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>59-62<br/></td>\n<td>Grass grows in 160-sq. -ft. area before the rod, or grass existing there grows to ten times normal size.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>63-65<br/></td>\n<td>Turn ethereal any nonliving object of up to 1,000 lb. mass and up to 30 cu. ft. in size.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>66-69<br/></td>\n<td>Reduce wielder to 1/12 height (no save).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>70-79<br/></td>\n<td><i>Fireball</i> at target or 100 ft. straight ahead, 6d6 damage (Reflex DC 15 half).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>80-84<br/></td>\n<td><i>Invisibility</i> covers rod wielder.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>85-87<br/></td>\n<td>Leaves grow from target if within 60 ft. of rod. These last 24 hours.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>88-90<br/></td>\n<td>10-40 gems, value 1 gp each, shoot forth in a 30-ft. -long stream. Each gem deals 1 point of damage to any creature in its path: Roll 5d4 for the number of hits and divide them among the available targets.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>91-95<br/></td>\n<td>Shimmering colors dance and play over a 40-ft. -by-30-ft. area in front of rod. Creatures therein are blinded for 1d6 rounds (Fortitude DC 15 negates).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>96-97<br/></td>\n<td>Wielder (50% chance) or target (50% chance) turns permanently blue, green, or purple (no save).<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>98-100<br/></td>\n<td><i>Flesh to stone</i> (or <i>stone to flesh</i> if target is stone already) if target is within 60 ft. (Fortitude DC 18 negates).<br/></td>\n\n</tr>\n</table><p>Moderate enchantment; CL 10th; Craft Rod, <i>confusion</i>, creator must be chaotic; Price 12,000 gp.</p><p/>\n</div>\n    ','SRD 3.5 MagicItemsIII');
